                if inp[r][c]!=0 and (r,c) not in seen:
                    cells=[(rr,cc) for rr in range(r,H) for cc in range(c,W) if inp[rr][cc]==inp[r][c]]
                    if all(inp[rr][cc]==inp[r][c] for rr,cc in cells) and len(cells)>1:
                        seen.add((r,c))
                        seg.append((inp[r][c],cells))
        objs.append(seg)
    # assign objects to bands, swap outer bands
    n=len(bands)
    order=list(range(n))
    for i in range(n//2): order[i],order[n-1-i]=n-1-i,i
    res=[[0]*W for _ in range(H)]
