def content(g):
    H=len(g);W=len(g[0]); seen=set(); out=[]
    for r in range(H):
        for c in range(W):
            v=g[r][c]
            if v!=0 and (r,c) not in seen:
                # gather same-color component
                comp=set()
                stack=[(r,c)]
                while stack:
                    rr,cc=stack.pop()
                    if (rr,cc) in comp: continue
                    comp.add((rr,cc))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=rr+dr,cc+dc
                        if 0<=nr<H and 0<=nc<W and g[nr][nc]==v and (nr,nc) not in comp:
                            stack.append((nr,nc))
                out.append((v,comp))
    return out
