from collections import Counter, deque
def comps(g,bg):
    H=len(g);W=len(g[0]);seen=set();out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and (i,j) not in seen:
                col=g[i][j];q=deque([(i,j)]);seen.add((i,j));cells=[]
                while q:
                    r,c=q.popleft();cells.append((r,c))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=r+dr,c+dc
                        if 0<=nr<H and 0<=nc<W and g[nr][nc]==col and (nr,nc) not in seen:
                            seen.add((nr,nc));q.append((nr,nc))
                out.append((col,sorted(cells)))
    return out
def norm(cl):
    rs=[r for r,_ in cl];cs=[c for _,c in cl]
    return tuple(sorted((r-min(rs),c-min(cs)) for r,c in cl))
def dihe8(cl):
    s=set();cur=list(cl)
    for _ in range(4):
        cur=[list(r) for r in zip(*cur)]
        flat=[(r,c) for r in range(len(cur)) for c in range(len(cur[0])) if cur[r][c]]
        for f in (flat,[ (r,len(flat)-1-c) for r,c in flat]):
            s.add(norm(f))
    return list(s)
